// Node.js Express Example for handling a POST request
app.post('/api/users', async (req, res) => {
  // 1. Extract the data from the Request Body
  const { username, email } = req.body;

  // 2. Validate the data
  if (!email) return res.status(400).send("Email is required");

  // 3. Create the new resource in the database
  const newUser = await db.users.create({ username, email });

  // 4. Return a 201 (Created) status with the new object
  res.status(201).json(newUser);
});
